  founder_sales_playbook: {
    id: 'founder_sales_playbook',
    title: '82. FLOWFORGE FOUNDER SALES OPERATING SYSTEM',
    subtitle: 'Founder-led revenue playbook and high-conversion conversation rules.',
    category: 'Founder Masterclass',
    tag: 'Sales Playbook',
    summary: 'The 7 non-negotiable rules of founder-led sales by Chuck Oduagu: leading with instability, selling diagnosis before platform, using category authority, and closing with binary choices.',
    content: `FOUNDER SALES OPERATING SYSTEM — CHUCK ODUAGU

Rule 1 — Lead with instability
Engineering leaders feel instability every day. You name it. You quantify it. You solve it.

Rule 2 — Sell the audit first
Never sell the platform first. Sell the diagnosis. The audit ($15k) is the frictionless wedge that exposes the undeniable need for the full OS.

Rule 3 — Use founder authority
You are the category creator. You are the stability expert. You are the Engineering OS founder. Speak with inevitability and calm conviction.

Rule 4 — Expand pain before offering solution
Ask:
• “Where do you feel instability right now?”
• “Where is your team overloaded?”
• “Where do deadlines slip most unexpectedly?”
Let them talk. Listen intently. Then show them how the audit maps that exact risk.

Rule 5 — Close with a binary choice
Always ask:
“Do you want me to run your audit this month or next month?”
Never ask:
“Would you like to move forward?” or “What do you think?”

Rule 6 — Founder-led deals close faster
You close ESA deals personally. You close onboarding deals personally. Autopilot MRR renewals can be managed by team and account reps later.

Rule 7 — Always anchor to stability
• Stability = Money (protected revenue and headcount efficiency)
• Stability = Morale (zero burnout departures)
• Stability = Velocity (unblocked flow)
• Stability = Predictability (board confidence)`
  },

