  enterprise_sales_playbook_full: {
    id: 'enterprise_sales_playbook_full',
    title: '98. FLOWFORGE FULL ENTERPRISE SALES PLAYBOOK (END-TO-END)',
    subtitle: 'The complete enterprise sales methodology from initial discovery to 7-figure expansion.',
    category: 'GTM & Launch',
    tag: 'Enterprise Playbook',
    summary: 'The 6-phase enterprise sales methodology: Discovery (exposing instability), ESA Pitch ($15k wedge), ESA Delivery (creating onboarding pull), Onboarding Proposal ($60k-$150k), Autopilot Activation ($8k-$25k/mo), and Marketplace Expansion.',
    content: `FLOWFORGE FULL ENTERPRISE SALES PLAYBOOK (END-TO-END)
The complete methodology for closing $50k–$250k+ engineering leadership deals.

Phase 1 — Discovery (Founder-Led Diagnosis)
• Goal: Expose hidden engineering overload and dependency fragility.
• Mandatory Diagnostic Questions:
  - “Where do you feel organizational instability and friction right now?”
  - “Where do deadlines and major release commitments slip unexpectedly?”
  - “Which engineering teams are operating with zero slack buffers?”
  - “Where are cross-service dependencies most fragile?”
• Execution: Let the executive talk without interruption. Mirror their frustration. Frame overload as a systems defect, not an engineer failure.

---

Phase 2 — ESA Diagnostic Pitch (The Frictionless Wedge)
• Core Narrative:
  “Engineering doesn’t fail because of poor code — it fails because systems are overloaded. Jira and DORA only measure past activity; FlowForge quantifies real-time cognitive load and predictive critical path collapse.”
• The Offer: 2 weeks, non-invasive metadata ingestion, minimal team lift, $15,000 flat.
• The Close: “Do you want me to run your audit this month or next month?”

---

Phase 3 — ESA Delivery (Exposing Fragility & Creating Urgency)
• Executive Presentation: Walk through the 5 deliverables (Stability Score, Critical Path DAG, Burnout Trajectory, Velocity Forecast, Recommendations).
• Strategic Frame: Demonstrate that continuing with unmonitored load instability will cause immediate sprint failure and expensive developer attrition. Make onboarding the only logical next step.

---

Phase 4 — Onboarding Proposal (Systemic Resolution)
• Packaging: 6–10 week implementation ($60,000–$150,000).
• Deliverables: Load baseline modeling, topological mapping, AI pair calibration, and compliance engine activation (Texas Tax Code §151.0101 / §151.351).
• The Close: “Should we start onboarding this month or next month?”

---

Phase 5 — AI Autopilot Activation (Recurring MRR Engine)
• Transition: Once stability is established, Autopilot automates real-time load rebalancing and burnout prevention.
• Investment: $8,000–$25,000 per team per month.

---

Phase 6 — FFX Marketplace Expansion (AWS-Style Usage Revenue)
• Expansion: Introduce slack tokenization and capacity trading credits for cross-team burst capacity and emergency critical path rescue.`
  },

